import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listMySpacesHandler } from "../handlers/listMySpacesHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listMySpacesHandler>>;

export function useListMySpaces(
  bookmark?: string | null,
  activeOnly?: boolean | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listMySpaces", bookmark, activeOnly],
    queryFn: () => listMySpacesHandler(bookmark, activeOnly),
    ...options,
  });
}
